fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let n = numbers.len();
    
    // Handle empty input
    if n == 0 {
        return Vec::new();
    }
    
    // Allocate result vector with exact capacity
    let mut result = Vec::with_capacity(2 * n - 1);
    
    // Process all but the last element
    for i in 0..(n - 1) {
        result.push(numbers[i]);
        result.push(delim);
    }
    
    // Add the last element without trailing delimiter
    result.push(numbers[n - 1]);
    
    result
}